import java.time.LocalDate;

/** A hold on a person, from a date (or from the beginning of time when it has none) to a date (or with
 *  no end when it has none), both inclusive. */
@Entity
@Table(name = "person_hold")
public class PersonHold {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** The first day the hold covers; none when it covers from the beginning of time. */
    @Column(name = "from_date")
    private LocalDate fromDate;

    /** The last day the hold covers; none while it has no end. */
    @Column(name = "to_date")
    private LocalDate toDate;

    protected PersonHold() {
    }

    PersonHold(LocalDate fromDate, LocalDate toDate) {
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public Long getId() {
        return id;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    /** Whether the hold covers a date. */
    public boolean covers(LocalDate date) {
        return (fromDate == null || !date.isBefore(fromDate)) && (toDate == null || !date.isAfter(toDate));
    }
}
-- A person may have several holds over time, each from a date and, optionally, to a date (both
-- inclusive). While a hold covers an OPEN or PENDING claim's date, and no statement bound it, the
-- claim counts in no live total. A person held before holds were dated keeps a hold from the
-- beginning of time (no from-date) with no end.
CREATE TABLE person_hold (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE,
    to_date   DATE
);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, NULL, NULL FROM person WHERE held;
